def separate_paren_groups(paren_string: str) -> List[str]:
    # Ignore spaces
    s = paren_string.replace(" ", "")
    groups = []
    depth = 0
    start = 0
    for i, char in enumerate(s):
        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1
            if depth == 0:
                groups.append(s[start:i+1])
                start = i + 1
    return groups

