    x, y = point
    # List to store indices of carpets that cover the point
    covering_indices = []
    for i in range(n):
        if i >= len(carpets):
            break
        a, b, g, k = carpets[i]
        # Carpet covers from (a, b) to (a + g, b + k)
        # The point (x, y) is covered if a <= x <= a + g and b <= y <= b + k
