def find_number_combinations():
    result = []
    for first in range(123, 987):
        digits = set(str(first))
        if len(digits) != 3 or '0' in digits:
            continue
        second = first * 2
        third = first * 3
        # Check if second and third also have exactly 3 digits
        if second > 999 or third > 999:
            continue
        digits_second = set(str(second))
        digits_third = set(str(third))
        if len(digits_second) != 3 or len(digits_third) != 3:
            continue
        if '0' in digits_second or '0' in digits_third:
            continue
        # Check no repetition of digits across all three numbers
        all_digits = digits | digits_second | digits_third
        if len(all_digits) != 9:
            continue
        result.append((first, second, third))
    return sorted(result, key=lambda x: x[0])

