def max_product(num_str: str, N: int, K: int) -> int:
    # dp[i][j] = maximum product obtainable from first i digits with j multiplication signs inserted
    # We have N-1 possible positions to insert signs (between consecutive digits)
    # If we insert K signs, we split the number into K+1 segments

    # Edge cases
    if N == 0:
        return 0
    if K == 0:
        # No signs to insert, product is the whole number
        try:
            return int(num_str)
        except:
            return 0

    # dp[i][j]: consider first i digits (1-indexed, so i from 1 to N), insert j signs
    # j ranges from 0 to K
    # Base case: j=0, dp[i][0] = int(num_str[:i])

    # dp[i][j] = max over all possible positions for the last sign
    # The last sign is between position t and t+1, where t ranges from j to i-1
    # (we need at least j digits before to place j signs in the first part, and at least 1 digit after)
    # Actually, we need to have j signs in the first t digits, and 0 signs in the last (i-t) digits
    # So dp[i][j] = max_{t from j to i-1} of dp[t][j-1] * int(num_str[t:i])

    # Let's do it with a 2D DP array
    # dp[i][j] for i in range(1, N+1), j in range(0, K+1)

    # Initialize with -infinity or None
    dp = [[-1] * (K + 1) for _ in range(N + 1)]

    # Base case: j = 0
    for i in range(1, N + 1):
        try:
            dp[i][0] = int(num_str[:i])
        except:
            dp[i][0] = 0

    # Fill for j from 1 to K
    for j in range(1, K + 1):
        for i in range(1, N + 1):
            # To have j signs in first i digits, we need at least j+1 digits (each sign separates two digits)
            if i < j + 1:
                dp[i][j] = -1  # impossible
                continue
            best = -1
            # The last sign can be placed at position t-1 to t, where t is the start of the last segment
            # t ranges from j to i-1 (need at least j digits for j-1 signs in first part, so t >= j)
            # Actually: first part has j-1 signs, needs at least j digits (j-1 signs -> j segments -> at least j digits)
            # Last part has 0 signs, needs at least 1 digit, so t <= i-1
            # t is the number of digits in the first part
            for t in range(j, i):
                # t = number of digits in first part, so first part is num_str[:t], last part is num_str[t:i]
                if dp[t][j-1] >= 0:
                    try:
                        last_part = int(num_str[t:i])
                    except:
                        last_part = 0
                    product = dp[t][j-1] * last_part
                    if product > best:
                        best = product
            dp[i][j] = best

    return dp[N][K]

