def count_passing_ways(n: int, m: int) -> int:
    if n < 1 or m < 0:
        return 0
    if m == 0:
        return 1

    dp = [0] * n
    dp[0] = 1

    for _ in range(m):
        new_dp = [0] * n
        for i in range(n):
            left = (i - 1) % n
            right = (i + 1) % n
            new_dp[left] += dp[i]
            new_dp[right] += dp[i]
        dp = new_dp

    return dp[0]

