def process_random_numbers(numbers: List[int]) -> Tuple[int, List[int]]:
    # Handle edge case: if input is not a list, return (0, [])
    if not isinstance(numbers, list):
        return (0, [])

    # Filter out non-integer elements
    valid_numbers = [num for num in numbers if isinstance(num, int)]

    # Remove duplicates using set
    unique_numbers = set(valid_numbers)

    # Sort the unique numbers in ascending order
    sorted_unique_numbers = sorted(unique_numbers)

    # Return the count and the sorted list
    return (len(sorted_unique_numbers), sorted_unique_numbers)

