def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if n < 0 or m < 0:
        return 0
    if m == 0 or not items:
        return 0

    # dp[j] = max importance with budget j
    dp = [0] * (n + 1)

    for i in range(m):
        if i >= len(items):
            break
        price, importance = items[i]
        # Update from high to low to avoid using same item twice
        for j in range(n, price - 1, -1):
            if dp[j - price] + importance > dp[j]:
                dp[j] = dp[j - price] + importance

    return dp[n]

