def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort applicants by score descending, then by registration number ascending
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Calculate the number of interviewees: 150% of m, rounded down
    num_interviewees = int(m * 1.5)

    # Edge case: if num_interviewees is 0, no one qualifies
    if num_interviewees == 0:
        return (0, [])

    # If num_interviewees is greater than the number of applicants, use all applicants
    if num_interviewees >= len(sorted_applicants):
        cutoff = sorted_applicants[-1][1]
        qualified = sorted_applicants
    else:
        cutoff = sorted_applicants[num_interviewees - 1][1]
        # Include all applicants with score >= cutoff
        qualified = [applicant for applicant in sorted_applicants if applicant[1] >= cutoff]

    return (cutoff, qualified)

