def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    # If last is 0 or less than 1, no valid sequences can be formed
    if last <= 0:
        return 0

    # Count the sequence that ends here (just the current sequence)
    count = 1

    # For each valid next number (1 to last // 2), recursively count sequences
    for next_num in range(1, last // 2 + 1):
        count += count_sequences(n, next_num, memo)

    memo[last] = count
    return count

