def preorder_traversal(inorder: str, postorder: str) -> str:
    def build(post_in, in_start, in_end):
        if post_in == in_end:
            return ""
        root = postorder[post_in]
        in_root = inorder.index(root)
        left_size = in_root - in_start
        res = root
        res += build(post_in + 1, in_start, in_root)
        res += build(post_in + 1 + left_size, in_root + 1, in_end)
        return res

    if not inorder and not postorder:
        return ""
    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder traversals must be of the same length")

    return build(0, 0, len(inorder))

