def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    # Handle edge case: if already equal
    if A == B:
        return 0

    # BFS
    queue = deque()
    queue.append((A, 0))
    visited = {A}

    max_steps = 10

    while queue:
        current, steps = queue.popleft()

        if steps >= max_steps:
            continue

        # Try all rules on the current string
        for rule in rules:
            if len(rule) != 2:
                continue
            source, target = rule
            if not isinstance(source, str) or not isinstance(target, str):
                continue

            # Find all occurrences of source in current
            start = 0
            while True:
                idx = current.find(source, start)
                if idx == -1:
                    break
                # Apply the rule
                new_string = current[:idx] + target + current[idx + len(source):]

                if new_string == B:
                    return steps + 1

                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))

                start = idx + 1

    return "NO ANSWER!"

