def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.
    """
    # Get the participants who made statements
    participants = set(statements.keys())

    # For each participant, check their statements
    for participant, part_statements in statements.items():
        # For each statement made by this participant
        for statement in part_statements:
            # Skip statements about the day of the week
            if any(day in statement.upper() for day in days_of_week):
                continue

            # Parse the statement to check consistency with the scenario
            # A statement is consistent if:
            # - If the participant is a liar, the statement must be FALSE (inconsistent with scenario)
            # - If the participant is not a liar, the statement must be TRUE (consistent with scenario)

            # Normalize the scenario name to uppercase for comparison
            scenario_upper = scenario.upper()
            statement_upper = statement.upper()

