def max_herb_value(T: int, M: int, herbs: list) -> int:
    # Edge case: if T is 0, we can't pick any herb
    if T <= 0 or M <= 0:
        return 0

    # Initialize dp array with zeros
    dp = [0] * (T + 1)

    # 0/1 knapsack iteration: for each herb, update dp in reverse order
    for time_cost, value in herbs:
        if time_cost > T:
            continue
        for t in range(T, time_cost - 1, -1):
            if dp[t - time_cost] + value > dp[t]:
                dp[t] = dp[t - time_cost] + value

    return dp[T]

