def minimum_students_to_leave(heights):
    if not heights:
        return 0

    n = len(heights)
    if n == 1:
        return 0

    # Longest Increasing Subsequence (LIS) ending at each position
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[j] < heights[i]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Longest Decreasing Subsequence (LDS) starting at each position
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                lds[i] = max(lds[i], lds[j] + 1)

    # The longest choir formation is the maximum of lis[i] + lds[i] - 1 (to avoid double counting i)
    max_formation = max(lis[i] + lds[i] - 1 for i in range(n))

    # Minimum number of students to leave
    return n - max_formation

